using FarmWorking.Application.Abstractions; using FarmWorking.Domain.Entities; using FarmWorking.Domain.Enums; using FarmWorking.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace FarmWorking.Infrastructure.Repositories;
public class TransactionRepository(FarmDbContext db):ITransactionRepository
{
    public IReadOnlyList<FarmTransaction> GetAll()=>db.FarmTransactions.AsNoTracking().OrderByDescending(x=>x.TransactionDate).ToList(); public IReadOnlyList<FarmTransaction> GetRecent(int count)=>db.FarmTransactions.AsNoTracking().OrderByDescending(x=>x.TransactionDate).Take(count).ToList(); public IReadOnlyList<FinanceTag> GetTags()=>db.FinanceTags.AsNoTracking().OrderBy(x=>x.Name).ToList(); public FinanceTag? FindTag(Guid id)=>db.FinanceTags.Find(id); public FarmTransaction? Find(Guid id)=>db.FarmTransactions.Find(id); public bool TagExists(string name,TransactionType type)=>db.FinanceTags.Any(x=>x.Type==type&&x.Name==name); public decimal Sum(TransactionType type)=>db.FarmTransactions.Where(x=>x.Type==type).Sum(x=>(decimal?)x.Amount)??0; public void Add(FarmTransaction item)=>db.FarmTransactions.Add(item); public void AddTag(FinanceTag tag)=>db.FinanceTags.Add(tag); public void RemoveTag(FinanceTag tag)=>db.FinanceTags.Remove(tag); public void Remove(FarmTransaction item)=>db.FarmTransactions.Remove(item); public Task SaveChangesAsync(CancellationToken ct=default)=>db.SaveChangesAsync(ct);
}
